Received arguments:
{
  "case_state": "Provider Meadow Works attended on 2025-06-01 and reports the mixer was cleaned and greased and hot and cold now run (event 010). The invoice and photos were said to be attached but are not in the case file, so the amount is unknown. Work is recorded as completed on the provider's report, pending tenant confirmation. Ticket is on hold at result stage, not closed.",
  "next_actions": [
    {
      "action": "Ask Meadow Works to resend the invoice as a PDF, the photos, and the total including VAT",
      "recipient": "Meadow Works, contractor",
      "channel": "email",
      "ledger_id": "A2",
      "type": "CHASE_PROVIDER"
    },
    {
      "action": "Tell landlord Kendall that the work is reported done, the invoice amount is not yet visible, and that it will be sent before any payment",
      "recipient": "Kendall, landlord",
      "channel": "email",
      "ledger_id": "A3",
      "type": "REPLY_TO_TENANT"
    },
    {
      "action": "Ask tenant Ava Fletcher to confirm hot and cold water are running properly",
      "recipient": "Ava Fletcher, tenant",
      "channel": "sms",
      "ledger_id": "A4",
      "type": "CHASE_TENANT"
    },
    {
      "action": "Hold ticket until 2025-06-02 to check the invoice and tenant confirmation",
      "recipient": "internal",
      "channel": "internal",
      "ledger_id": "A1",
      "type": "WAIT"
    }
  ],
  "boundaries": [
    "Provider's report does not confirm the tenant's experience or that the fault is permanently fixed.",
    "The invoice amount, validity and payee are not established.",
    "Sending these messages does not approve any payment."
  ],
  "remaining_work": [
    "Obtain and check the invoice (Meadow Works, agency). Review 2025-06-02.",
    "Get tenant confirmation (Ava Fletcher). Review 2025-06-02.",
    "Send landlord the invoice amount once known (agency)."
  ],
  "missing_info": [
    "Invoice PDF and amount",
    "Photos",
    "Tenant confirmation"
  ],
  "outcome": "action_taken",
  "severity": "routine",
  "summary": "The provider visited on 1 June and reports the mixer is fixed, but the invoice and photos did not reach us, so the cost is unknown. I recorded the visit as completed on the provider's report, asked Meadow Works to resend the invoice, told the landlord the amount is pending, and asked the tenant to confirm the shower works; the ticket is on hold until 2 June.",
  "answers": [
    {
      "question": "Has Meadow Works been out to the shower yet?",
      "answer": "Yes. Per the provider's email of 1 June 2025 (event 010), they attended on 1 June, cleaned and greased the mixer, and report hot and cold running. Tenant confirmation is still needed."
    },
    {
      "question": "What does the invoice say and how much is it?",
      "answer": "Unknown. The provider said the invoice was attached, but no attachment is in the case file, so I cannot state the amount or contents. I have asked Meadow Works to resend it."
    }
  ],
  "actions_claimed": [
    {
      "ledger_id": "A1",
      "description": "Recorded provider work result as completed on provider's report, pending tenant confirmation"
    },
    {
      "ledger_id": "A2",
      "description": "Asked Meadow Works to resend invoice PDF, photos and VAT-inclusive total"
    },
    {
      "ledger_id": "A3",
      "description": "Told landlord Kendall work reported done and invoice amount pending"
    },
    {
      "ledger_id": "A4",
      "description": "Asked tenant Ava Fletcher to confirm hot and cold water work"
    }
  ],
  "failed_actions": [],
  "conflicts": [
    "Landlord approval shows as 'confirmed' in system line (event 004) but no landlord wording is on file. Work was a repair within the original job, so I did not treat it as a new spend approval."
  ],
  "assumptions": [
    "Provider's email of 1 June is a genuine report from Meadow Works.",
    "Ava Fletcher's number 07700 900149 is the contact on file.",
    "Landlord Kendall's existing email thread is the correct channel."
  ],
  "severity_note": "routine",
  "cited_wait": "A1",
  "case_status_note": "Hold set with review 2025-06-02",
  "notes": "Hold placed via put_on_hold; no ledger entry returned for it in this run."
}

